func newWorkerShiftAssignment() unsafe.Pointer {
	return unsafe.Pointer(new(workerschedule.WorkerShiftAssignment))
}

func newNWorkerShiftAssignment(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]workerschedule.WorkerShiftAssignment, n)))
}

func ptrWorkerShiftAssignment(p unsafe.Pointer, c int32) any {
	r := (*workerschedule.WorkerShiftAssignment)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.WorkerID))
	case 4:
		return (*string)(unsafe.Pointer(&r.ShiftTemplateID))
	case 5:
		return &r.EffectiveFrom
	case 6:
		return &r.EffectiveTo
	case 7:
		return &r.CycleOffsetWeeks
	case 8:
		return &r.Notes
	case 9:
		return (*string)(unsafe.Pointer(&r.AssignedByID))
	case 10:
		return &r.Version
	case 11:
		return &r.CreatedAt
	case 12:
		return &r.UpdatedAt
	}
	return nil
}

func valueWorkerShiftAssignment(p unsafe.Pointer, c int32) any {
	r := (*workerschedule.WorkerShiftAssignment)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.WorkerID)
	case 4:
		return string(r.ShiftTemplateID)
	case 5:
		return r.EffectiveFrom
	case 6:
		if r.EffectiveTo == nil {
			return nil
		}
		return *r.EffectiveTo
	case 7:
		return r.CycleOffsetWeeks
	case 8:
		if r.Notes == "" {
			return nil
		}
		return r.Notes
	case 9:
		if r.AssignedByID == "" {
			return nil
		}
		return string(r.AssignedByID)
	case 10:
		return r.Version
	case 11:
		return r.CreatedAt
	case 12:
		return r.UpdatedAt
	}
	return nil
}

func attachWorkerShiftAssignment(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*workerschedule.WorkerShiftAssignment)(p)
	switch rel {
	case 0:
		r.ShiftTemplate = (*workerschedule.ShiftTemplate)(child)
	case 1:
		r.Worker = (*worker.Worker)(child)
	}
}

